import{_ as a,o as e,c as l,a2 as r}from"./chunks/framework.DSoq407f.js";const u=JSON.parse('{"title":"插件中心","description":"","frontmatter":{},"headers":[],"relativePath":"console/plugins.md","filePath":"console/plugins.md","lastUpdated":1782304957000}'),o={name:"console/plugins.md"};function i(d,t,n,s,h,c){return e(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="插件中心" tabindex="-1">插件中心 <a class="header-anchor" href="#插件中心" aria-label="Permalink to &quot;插件中心&quot;">​</a></h1><blockquote><p><strong>你会学到</strong>：怎么找插件、购买、安装到机器人、配置。</p></blockquote><h2 id="浏览插件" tabindex="-1">浏览插件 <a class="header-anchor" href="#浏览插件" aria-label="Permalink to &quot;浏览插件&quot;">​</a></h2><p>插件中心展示所有已上架的插件，支持：</p><ul><li>按分类筛选（游戏 / 系统 / 工具 / 娱乐 / 社交 / AI 等）。</li><li>搜索关键词。</li><li>按热门 / 最新排序。</li></ul><p>每个插件卡片显示：名称、作者、简介、价格、分类。</p><h2 id="购买-安装" tabindex="-1">购买 / 安装 <a class="header-anchor" href="#购买-安装" aria-label="Permalink to &quot;购买 / 安装&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>流程</th></tr></thead><tbody><tr><td><strong>免费插件</strong></td><td>直接点「安装」即可</td></tr><tr><td><strong>付费插件</strong></td><td>点「购买」→ 余额支付 → 自动安装</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">套餐含插件</p><p>某些订阅套餐已包含指定插件（见<a href="./subscriptions">我的订阅</a>），这些插件无需单独购买。</p></div><h2 id="绑定到机器人" tabindex="-1">绑定到机器人 <a class="header-anchor" href="#绑定到机器人" aria-label="Permalink to &quot;绑定到机器人&quot;">​</a></h2><p>安装插件后，需要把它<strong>绑定到具体的机器人</strong>才会运行：</p><ol><li>进入某个机器人的「已安装插件」。</li><li>启用要用的插件。</li><li>配置插件参数（如有 <code>setting.json</code>）。</li></ol><p>一个插件可以绑到多个机器人，各自独立配置、独立运行。</p><h2 id="配置插件" tabindex="-1">配置插件 <a class="header-anchor" href="#配置插件" aria-label="Permalink to &quot;配置插件&quot;">​</a></h2><p>插件的配置项由开发者通过 <code>setting.json</code> 定义（见<a href="./../plugin-dev/settings">插件开发 · 配置项</a>）。常见配置：</p><ul><li>触发关键词</li><li>管理员列表</li><li>运行模式</li><li>API 密钥等</li></ul><p>改完保存即生效（约 30 秒缓存延迟）。</p><h2 id="插件管理" tabindex="-1">插件管理 <a class="header-anchor" href="#插件管理" aria-label="Permalink to &quot;插件管理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td>启用 / 停用</td><td>临时开关，不卸载</td></tr><tr><td>卸载</td><td>从机器人移除</td></tr><tr><td>升级</td><td>插件有新版本时提示升级</td></tr><tr><td>优先级</td><td>多个插件时的执行顺序</td></tr><tr><td>拦截器开关</td><td>是否启用该插件的出站拦截</td></tr></tbody></table><h2 id="已购买记录" tabindex="-1">已购买记录 <a class="header-anchor" href="#已购买记录" aria-label="Permalink to &quot;已购买记录&quot;">​</a></h2><p>在账户里查看你买过的所有插件、购买时间、状态。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>机器人怎么配 → <a href="./bots">机器人管理</a></li><li>想自己开发插件 → <a href="./../plugin-dev/getting-started">插件开发</a></li></ul>',23)])])}const b=a(o,[["render",i]]);export{u as __pageData,b as default};
